function fromBase13(s) {
    const digits = '0123456789ABC';
    const neg = s.startsWith('-');
    if (neg) s = s.slice(1);
    let result = 0;
    for (const ch of s.toUpperCase()) {
        result = result * BASE + digits.indexOf(ch);
    }
    return neg ? -result : result;
}

