/**
 * Heady Circuit Breaker — Resilience primitive
 * Prevents cascade failures by tracking error rates per service
 * and opening the circuit when thresholds are exceeded.
 *
 * States: CLOSED (normal) → OPEN (failing) → HALF_OPEN (testing recovery)
 */

class CircuitBreaker {
    constructor(name, options = {}) {
        this.name = name;
        this.failureThreshold = options.failureThreshold || 5;
        this.resetTimeoutMs = options.resetTimeoutMs || 30000;
        this.halfOpenMaxCalls = options.halfOpenMaxCalls || 3;
        this.monitorWindowMs = options.monitorWindowMs || 60000;

        this.state = 'CLOSED';
        this.failures = 0;
        this.successes = 0;
        this.halfOpenCalls = 0;
        this.lastFailureTime = null;
        this.lastStateChange = Date.now();
        this.metrics = { totalCalls: 0, totalFailures: 0, totalSuccesses: 0, trips: 0 };
    }

    /**
     * Execute a function through the circuit breaker
     * @param {Function} fn - async function to execute
     * @param {Function} [fallback] - optional fallback when circuit is open
     * @returns {Promise<any>} result
     */
    async execute(fn, fallback) {
        this.metrics.totalCalls++;

// Queue the request
        return new Promise((resolve, reject) => {
            const timer = setTimeout(() => {
                const idx = this.queue.findIndex(q => q.timer === timer);
                if (idx !== -1) this.queue.splice(idx, 1);
                this.metrics.timeouts++;
                reject(new PoolTimeoutError(`Pool "${this.name}" queue timeout after ${this.timeoutMs}ms`));
            }, this.timeoutMs);

            this.queue.push({ fn, resolve, reject, timer });
            this.metrics.queued++;
        });
    }

    async _run(fn) {
        this.active++;
        this.metrics.acquired++;
        try {
            return await fn();
        } finally {
            this.active--;
            this.metrics.released++;
            this._drainQueue();
        }
    }

    _drainQueue() {
        if (this.queue.length > 0 && this.active < this.maxConcurrent) {
            const next = this.queue.shift();
            clearTimeout(next.timer);
            this._run(next.fn).then(next.resolve).catch(next.reject);
        }
    }

