      subject,
      context,
      status: 'queued',
      priority: context.priority || 'normal'
    };

    this.validationQueue.push(validation);

    // Sort by priority
    this.validationQueue.sort((a, b) => {
      const priorities = { critical: 3, high: 2, normal: 1, low: 0 };
      return (priorities[b.priority] || 1) - (priorities[a.priority] || 1);
    });

    this.emit('validation_queued', validation);
    console.log(`🤔 Validation queued: ${subject} (${validation.id})`);

    return validation.id;
  }

async askQuestion(question, validation) {
    // Update question metrics
    const effectiveness = this.learningData.questionEffectiveness.get(question.id);
    effectiveness.totalAsked++;
    effectiveness.lastAsked = Date.now();

    // Simulate question answering based on context
    let score = 0.8; // Base score
    let response = "Positive response";

    // Adjust score based on validation context
    if (validation.context && validation.context.complexity === 'high') {
      score -= 0.1; // Harder to pass critical questions for complex changes
    }

    if (validation.context && validation.context.impact === 'low') {
      score += 0.1; // Easier for low-impact changes
    }

    // Adjust based on question criticality
    if (question.critical) {
      score -= 0.05; // Slightly harder to pass critical questions
    }

    // Add some randomness for simulation
    score += (Math.random() - 0.5) * 0.2;

    score = Math.max(0, Math.min(1, score));

    // Generate contextual response
    if (score > 0.8) {
      response = "Strong positive response with clear justification";
    } else if (score > 0.6) {
      response = "Moderate response with some concerns noted";
    } else {
      response = "Concerning response requiring further investigation";
    }

    return {
      score,
      response,
      confidence: 0.9,
      timestamp: Date.now()
    };
  }

updateMetrics() {
    if (!this.isRunning) return;

    const recentValidations = this.completedValidations.slice(-100);

    if (recentValidations.length > 0) {
      this.metrics.averageScore = recentValidations.reduce((sum, v) => sum + v.results.totalScore, 0) / recentValidations.length;
      this.metrics.approvalRate = recentValidations.filter(v => v.results.approved).length / recentValidations.length;
    }

    this.metrics.uptime = Date.now() - this.startTime;
    this.metrics.lastValidation = Date.now();

    this.emit('metrics_updated', this.metrics);
  }

  getStatus() {
    return {
      isRunning: this.isRunning,
      uptime: this.metrics.uptime,
      validationsProcessed: this.metrics.validationsProcessed,
      queueSize: this.validationQueue.length,
      processingValidations: this.processingValidations.size,
      averageScore: this.metrics.averageScore,
      approvalRate: this.metrics.approvalRate,
      ethicalViolations: this.metrics.ethicalViolations,
      lastValidation: this.metrics.lastValidation
    };
  }

// ── Federated Write (fan-out to all tiers) ──────────────────────
async function federatedInsert(entry) {
    const payload = {
        id: entry.id,
        content: entry.content,
        embedding: entry.embedding,
        metadata: entry.metadata,
    };

    // Fan-out: write to all available tiers in parallel
    // Local shard write happens in vector-memory.js ingestMemory
    const promises = [];

    // Edge
    promises.push(
        edgeVectorize("insert", { vectors: [payload] })
            .catch(() => null)
    );

    // GCloud
    promises.push(
        gcloudVector("insert", payload)
            .catch(() => null)
    );

    // Colab
    promises.push(
        colabRoute("insert", payload)
            .catch(() => null)
    );

    const results = await Promise.allSettled(promises);
    const successes = results.filter(r => r.status === "fulfilled" && r.value !== null).length;
    return { tiersWritten: successes + 1, tiers: ["local", "edge", "gcloud", "colab"].slice(0, successes + 1) };
}

// ── Federated Read (cascade through tiers) ──────────────────────
async function federatedQuery(queryEmbedding, topK = 5) {
    // Try edge first (fastest)
    const edgeResults = await edgeVectorize("query", { embedding: queryEmbedding, topK }).catch(() => null);
    if (edgeResults && edgeResults.length > 0) {
        return { results: edgeResults, tier: "edge", latency: tierMetrics.edge.avgLatency };
    }

async function embed(text) {
    const truncated = typeof text === "string" ? text.substring(0, 2000) : String(text).substring(0, 2000);

    // Strategy 1: HuggingFace Inference API (free tier, no token needed for public models)
    try {
        const hfRes = await fetch("https://router.huggingface.co/hf-inference/models/sentence-transformers/all-MiniLM-L6-v2/pipeline/feature-extraction", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                ...(process.env.HF_TOKEN ? { "Authorization": `Bearer ${process.env.HF_TOKEN}` } : {}),
            },
            body: JSON.stringify({ inputs: truncated }),
            signal: AbortSignal.timeout(8000),
        });
        if (hfRes.ok) {
            const data = await hfRes.json();
            const embedding = Array.isArray(data) ? (Array.isArray(data[0]) ? data[0] : data) : null;
            if (embedding && embedding.length >= 100) {
                remoteEmbedCount++;
                return embedding;
            }
        }
    } catch { /* HF API failed, try next */ }

candidates.forEach(v => {
            results.push({
                id: v.id,
                content: v.content,
                score: cosineSim(queryEmbedding, v.embedding),
                metadata: v.metadata,
                created: v.created,
                shard: shard.id,
                zone: v._zone,
                _3d: v._3d,
            });
        });
    });

    results.sort((a, b) => b.score - a.score);
    return results.slice(0, topK);
}

/**
 * Rebuild zone index from all shards
 */
function rebuildZoneIndex() {
    for (let i = 0; i < 8; i++) zoneIndex.set(i, []);
    shards.forEach(shard => {
        shard.vectors.forEach(v => {
            if (v._3d) {
                const zone = v._zone ?? assignZone(v._3d.x, v._3d.y, v._3d.z);
                v._zone = zone;
                zoneIndex.get(zone).push({ id: v.id, shardId: shard.id });
            }
        });
    });
}

// ── Persistence ─────────────────────────────────────────────────
const persistTimers = {};
function schedulePersist(shardIdx) {
    if (persistTimers[shardIdx]) return;
    persistTimers[shardIdx] = setTimeout(() => {
        try {
            const shard = shards[shardIdx];
            if (shard.dirty) {
                fs.writeFileSync(shard.path, JSON.stringify(shard.vectors, null, 0));
                shard.dirty = false;
            }
        } catch { }
        delete persistTimers[shardIdx];
    }, PERSIST_DEBOUNCE);
}

